// MSD Attribution Capture — Validate + Normalize + Hash
const crypto = require('crypto');

const expectedSecret = '9263794e1e4b3b7183395e490a7732b4653e8f501d760ac67e5ac57760546c01';
let body = $input.first().json.body || $input.first().json;

// GTM envía con fetch mode:'no-cors', que fuerza Content-Type text/plain:
// n8n no parsea el JSON y el body llega como string crudo
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { throw new Error('Invalid JSON body'); }
}

// Secret en body (porque GTM no-cors no permite custom headers)
if (body._secret !== expectedSecret) {
  throw new Error('Invalid secret');
}

const normalizeEmail = (e) => (e || '').toLowerCase().trim();
const normalizePhone = (p) => (p || '').replace(/[^0-9+]/g, '');
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');

const email = normalizeEmail(body.email);
const phone = normalizePhone(body.phone);

if (!email && !phone) {
  throw new Error('Need email or phone for matching');
}

const click_ids = body.click_ids || {};
const ga4 = body.ga4 || {};
const utm = body.utm || {};
const page = body.page || {};

return [{
  json: {
    email_hash: email ? sha256(email) : null,
    phone_hash: phone ? sha256(phone) : null,
    gclid: click_ids.gclid || null,
    gbraid: click_ids.gbraid || null,
    wbraid: click_ids.wbraid || null,
    fbclid: click_ids.fbclid || null,
    msclkid: click_ids.msclkid || null,
    ttclid: click_ids.ttclid || null,
    ga4_client_id: ga4.client_id || null,
    ga4_session_id: ga4.session_id || null,
    utm_source: utm.source || null,
    utm_medium: utm.medium || null,
    utm_campaign: utm.campaign || null,
    utm_content: utm.content || null,
    utm_term: utm.term || null,
    landing_page_url: page.landing_url || null,
    current_page_url: page.current_url || null,
    referrer: page.referrer || null,
    user_agent: page.user_agent || null,
    hs_form_id: body.hs_form_id || null,
    hs_submission_guid: body.hs_submission_guid || null,
    hs_portal_id: body.hs_portal_id || '24089924',
    location_hint: body.location_hint || null,
    raw_payload: JSON.stringify(body)
  }
}];
